B.U8=s(["\uc624\ub298 \uc6b4\uc740 \uc880 \uc26c\uc5b4\uac00\ub294 \uc911.\n\ub300\uc2e0 \ub9c8\uc74c\uc740 \uc4f8 \uc218 \uc788\uc5b4\uc694","\uc548 \ud480\ub9ac\ub294 \uac8c\n\ub2f9\uc2e0 \ud0d3\uc740 \uc544\ub2c8\uc5d0\uc694","\uc774\ub7f0 \ub0a0\ub3c4\n\uc9c0\ub098\uac00\uae34 \ud574\uc694","\uae30\ub300\ub294 \ub0ae\uac8c,\n\uce5c\uc808\uc740 \uadf8\ub300\ub85c","\uc624\ub298\uc740 \uc6b4 \ub9d0\uace0\n\uc2e4\ub825\uc73c\ub85c \uac00\ub294 \ub0a0\uc774\uc5d0\uc694","\uc774\ub7f0 \ub0a0\uc77c\uc218\ub85d\n\uba3c\uc800 \uc6c3\ub294 \ucabd\uc774 \ud3b8\ud574\uc694","\uc624\ub298\uc758 \ubaa9\ud45c\ub294\n\ubb34\uc0ac\ud788 \uc9d1\uc5d0 \uac00\uae30","\uc2e0\ud638\ub4f1\uc774 \ub2e4 \ube68\uac04\ubd88.\n\ucc9c\ucc9c\ud788 \uac00\ub77c\ub294 \ub73b\uc774\uc5d0\uc694","\uc5d8\ub9ac\ubca0\uc774\ud130\ub294 \uc624\ub298\n\ub298 \ubc18\ub300\ud3b8\uc5d0 \uc788\uc5b4\uc694","\uc774\uc5b4\ud3f0 \ud55c\ucabd\uc774\n\ub9d0\uc37d\ubd80\ub9b4 \uc218 \uc788\uc5b4\uc694","\ubc30\ud130\ub9ac 8% \uac19\uc740 \ud558\ub8e8.\n\ucda9\uc804\uc740 \ucc9c\ucc9c\ud788 \ud574\uc694","\uc6b0\uc0b0 \ucc59\uae30\ub294 \uac8c\n\ub9c8\uc74c \ud3b8\ud560 \uac70\uc608\uc694","\uc624\ub298 \uc880 \uc5b5\uc6b8\ud55c \uc77c\uc740\n\uadf8\ub0e5 \ud758\ub824\ubcf4\ub0b4\uc694","\uc6b4\uc740 \uc7a0\uae50 \uc790\ub9ac\ub97c \ube44\uc6e0\uc5b4\uc694.\n\uace7 \ub3cc\uc544\uc640\uc694","\uc870\uc2ec\uc870\uc2ec.\n\ub0b4\uc77c \ubaab\uc774 \uc313\uc774\ub294 \uc911\uc774\uc5d0\uc694","\ubcc4\uc77c \uc5c6\uc774 \uc9c0\ub098\uac00\uba74\n\uadf8\uac78\ub85c \ucda9\ubd84\ud55c \ub0a0\uc774\uc5d0\uc694"],t.s)
B.ZE=s(["\ub098\uc058\uc9c0 \uc54a\uc544\uc694.\n\ub531 \ud3c9\ud0c0\uc608\uc694","\ud3c9\ubc94\uc774 \uc81c\uc77c \uc5b4\ub835\ub2e4\ub358\ub370\n\ud574\ub0c8\ub124\uc694","\ubb34\ub09c\ud55c \ud558\ub8e8.\n\ubc18\uc804\uc740 \ud558\uae30 \ub098\ub984\uc774\uc5d0\uc694","\ubbf8\uc9c0\uadfc\ud55c \uc6b4\uc138.\n\uc628\ub3c4\ub294 \uc62c\ub9b4 \uc218 \uc788\uc5b4\uc694","\ubcc4\uc77c \uc5c6\ub294 \ud558\ub8e8.\n\uadf8\uac70 \uc740\uadfc \uadc0\ud574\uc694","\uae30\ubcf8\uae30 \ud0c4\ud0c4\ud55c\n\ud558\ub8e8\uac00 \ub420 \uac83 \uac19\uc544\uc694","\uc18c\uc18c\ud55c \ud589\uc6b4 \uc608\ubcf4.\n\uc6b0\uc0b0\uc740 \ud544\uc694 \uc5c6\uc5b4\uc694","\uce5c\uc808 \ud558\ub098\uba74\n\ud55c \uce78 \uc62c\ub77c\uac00\uc694","\ud0d5\ube44\uc2e4 \uac04\uc2dd,\n\ub9c8\uc9c0\ub9c9 \ud558\ub098\ub294 \ub2f9\uc2e0 \uac70\uc608\uc694","\ubc84\uc2a4\uac00 \ub531 \ub9de\uac8c\n\ub3c4\ucc29\ud558\ub294 \ud558\ub8e8\uc608\uc694","\ucee4\ud53c \uc628\ub3c4\uac00\n\ub531 \uc88b\uc744 \uac70\uc608\uc694","\uc624\ub298\uc758 \ubc18\uc804\uc740\n\uc624\ud6c4 3\uc2dc\ucbe4 \uc640\uc694","\uc791\uac8c \uc6c3\uc744 \uc77c\uc774\n\ub450 \ubc88\ucbe4 \uc788\uc5b4\uc694","\uc810\uc2ec \uba54\ub274\ub294\n\ub0a8\uc774 \uc815\ud574\uc904 \uac83 \uac19\uc544\uc694","\uc790\ud310\uae30 \uc55e\uc5d0\uc11c\n\uc624\ub798 \uace0\ubbfc\ud558\uac8c \ub3fc\uc694","\uc6b4\uc740 \uc794\uc794\ud574\uc694.\n\ud30c\ub3c4\ub294 \uc9c1\uc811 \ub9cc\ub4e4\uc5b4\uc694"],t.s)
B.VH=s(["\uc624\ub298 \uaf64 \ub9d1\uc544\uc694.\n\uc88b\uc740 \uc77c \uc608\uac10\uc774\uc5d0\uc694","\ud589\uc6b4 \uc2e0\ud638\ub4f1,\n\ucd08\ub85d\ubd88 \ub4e4\uc5b4\uc654\uc5b4\uc694","\ubb54\uac00 \ub420 \uac83 \uac19\uc740 \ub0a0.\n\uadf8 \ub290\ub08c \ub9de\uc544\uc694","\uc624\ub298 \uac74\ub128 \uce5c\uc808\uc740\n\uc774\uc790 \ubd99\uc5b4\uc11c \ub3cc\uc544\uc640\uc694","\ud0c0\uc774\ubc0d \uc88b\ub124\uc694.\n\ubbf8\ub904\ub454 \uac70 \uc624\ub298 \ud574\uc694","\uc624\ub298 \uc6c3\uc744 \uc77c\n\ud55c \ubc88\uc740 \uc788\uc5b4\uc694","\uc88b\uc740 \ub0a0\uc5d4\n\ub098\ub220\ub3c4 \uc548 \uc904\uc5b4\uc694","\uc2e0\ud638\ub4f1\uc774\n\uc774\uc0c1\ud558\uac8c \ub2e4 \ucd08\ub85d\ubd88","\ucc3e\ub358 \ubb3c\uac74\uc774\n\uc81c\uc790\ub9ac\uc5d0\uc11c \ub098\uc640\uc694","\uc5d8\ub9ac\ubca0\uc774\ud130\uac00 1\uce35\uc5d0\uc11c\n\uae30\ub2e4\ub9ac\uace0 \uc788\uc5b4\uc694","\uc8fc\uba38\ub2c8\uc5d0\uc11c \uc78a\uace0 \uc788\ub358\n\ub3c8\uc774 \ub098\uc62c \uc218 \uc788\uc5b4\uc694","\uae40\ubc25\uc5d0 \uacc4\ub780\uc774\n\ub450 \uac1c \ub4e4\uc5b4 \uc788\uc5b4\uc694","\uc154\ud50c \uccab \uace1\ubd80\ud130\n\uc778\uc0dd\uace1\uc77c \uac70\uc608\uc694","\ub204\uac00 \uba3c\uc800\n\uc5f0\ub77d\ud574 \uc62c \uac83 \uac19\uc544\uc694","\uc9c0\ud558\ucca0\uc5d0\uc11c\n\uc549\uc544\uc11c \uac08 \uc218 \uc788\uc5b4\uc694","\uc624\ub298 \uc0ac\uc9c4 \uc798 \ub098\uc640\uc694.\n\ud55c \uc7a5 \ub0a8\uaca8\ub450\uc138\uc694"],t.s)
